begin;
insert into public.ce_course2_resources(id,data) values
('course2_module1_pdf','{"base64": "", "sha256": "ac399f11c7707d7020cbbcb61e048b3ea1ca853711120cf45f64cdf6dcfc86a4", "filename": "CE_HALO_Course2_Module01_Brain_Death_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module1_questions','[{"module_id": "course_2_module_1", "question_id": "course_2_module_1_q01", "question_number": 1, "stem": "Which multi-society document is the current U.S. reference standard for brain death / death by neurologic criteria (BD/DNC) determination in both pediatric and adult patients? ]", "choice_a": "2023 AAN/AAP/CNS/SCCM multi-society consensus practice guideline", "choice_b": "1995 AAN adult brain death parameters (unrevised)", "choice_c": "2010 AAN adult and 2011 AAP/CNS/SCCM pediatric guidelines used separately", "choice_d": "2020 ASA statement on controlled DCD", "correct_choice": "a", "rationale": "Greer et al. (2023) unified pediatric and adult BD/DNC determination for the first time in a single multi-society consensus practice guideline, updating the 2010 adult AAN parameters and 2011 pediatric guidelines.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q02", "question_number": 2, "stem": "According to the 2023 NEJM randomized trial by Dhar and colleagues in 838 hemodynamically unstable brain-dead heart donors, IV levothyroxine compared with saline placebo: ]", "choice_a": "Was associated with a large reduction in vasopressor requirement", "choice_b": "Did NOT significantly increase the number of hearts transplanted and was associated with more severe hypertension and tachycardia", "choice_c": "Significantly increased the number of hearts transplanted", "choice_d": "Significantly improved donor ejection fraction", "correct_choice": "b", "rationale": "Hearts were transplanted from 54.9% vs 53.2% of donors (adjusted RR 1.01, 95% CI 0.97–1.07, p=0.57). Severe hypertension and tachycardia were more common with levothyroxine. Routine IV levothyroxine is no longer supported for unstable brain-dead heart donors.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q03", "question_number": 3, "stem": "A brain-dead donor develops abrupt polyuria of 500 mL/h with a rising serum sodium of 158 mEq/L. Which drip is most appropriate for the underlying pathophysiology? ]", "choice_a": "Nitroglycerin", "choice_b": "Dobutamine", "choice_c": "Vasopressin", "choice_d": "Norepinephrine", "correct_choice": "c", "rationale": "This is diabetes insipidus from posterior pituitary failure. Vasopressin replaces ADH, decreases free-water losses, and simultaneously supports blood pressure in vasodilatory shock.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q04", "question_number": 4, "stem": "A first-line vasoactive infusion for persistent hypotension in the brain-dead donor is most commonly: ]", "choice_a": "Milrinone", "choice_b": "Phenylephrine", "choice_c": "Isoproterenol", "choice_d": "Norepinephrine", "correct_choice": "d", "rationale": "Norepinephrine is the most common first-line vasopressor for persistent hypotension in donor management protocols.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q05", "question_number": 5, "stem": "Which anesthetic principle is TRUE for the brain-dead donor in the operating room? ]", "choice_a": "Medications are directed toward physiologic stability and organ preservation rather than treatment of pain or awareness", "choice_b": "Neuromuscular blockade is contraindicated", "choice_c": "Volatile anesthetics are mandatory throughout the case", "choice_d": "Opioids and sedative-hypnotics are required to prevent awareness", "correct_choice": "a", "rationale": "After BD/DNC declaration the donor is dead; medications are used to stabilize physiology and preserve organs. Spinal reflex movements may occur, so NMB is often used, but opioids/sedatives are not required for awareness or analgesia.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q06", "question_number": 6, "stem": "In the 2025 U.S. nationwide analysis of 21,010 DCD kidney transplants by Kusakabe and colleagues, NRP was associated with which change in delayed graft function compared with non-NRP DCD kidneys? ]", "choice_a": "DGF could not be assessed because of small sample size", "choice_b": "DGF decreased from 49.7% to 30.3%", "choice_c": "DGF increased from 30.3% to 49.7%", "choice_d": "DGF was unchanged", "correct_choice": "b", "rationale": "Kusakabe et al. (2026) reported DGF of 30.3% with NRP vs 49.7% without NRP, with also improved 3-year graft and patient survival.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q07", "question_number": 7, "stem": "Which sequence of organ removal is most typical during full multi-organ procurement? ]", "choice_a": "Liver → thoracic organs → kidneys → pancreas → vessels/tissues", "choice_b": "Pancreas → kidneys → thoracic organs → liver → tissues", "choice_c": "Thoracic organs → liver/intestine → pancreas → kidneys → vessels/tissues", "choice_d": "Kidneys → liver → thoracic organs → pancreas → tissues", "correct_choice": "c", "rationale": "The typical sequence reflects relative ischemic tolerance: thoracic organs first (most time-sensitive), then liver/intestine, then pancreas, then kidneys, then vessels and tissues.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q08", "question_number": 8, "stem": "A central procedural requirement of TA-NRP that distinguishes it ethically from cardiopulmonary bypass in a living patient is: ]", "choice_a": "Discontinuation of all monitoring before flow is initiated", "choice_b": "Use of a heparin-free circuit", "choice_c": "Avoidance of vasoactive medications during perfusion", "choice_d": "Prevention of any return of cerebral blood flow", "correct_choice": "d", "rationale": "Because circulation is restored after circulatory death, programs must surgically exclude cerebral circulation (e.g., aortic arch-vessel ligation and venting) before initiating perfusion to comply with the dead donor rule.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q09", "question_number": 9, "stem": "Which agent supports blood pressure AND directly treats diabetes insipidus in the brain-dead donor? ]", "choice_a": "Vasopressin", "choice_b": "Norepinephrine", "choice_c": "Dopamine", "choice_d": "Phenylephrine", "correct_choice": "a", "rationale": "Vasopressin provides both vasoconstriction (V1) and antidiuretic activity (V2), making it uniquely useful in donors with vasoplegia plus diabetes insipidus.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q10", "question_number": 10, "stem": "In the DCD pathway, current U.S. practice commonly requires a no-touch observation period AFTER circulatory arrest before death is declared. That observation period is typically: ]", "choice_a": "2 minutes", "choice_b": "5 minutes", "choice_c": "20 minutes", "choice_d": "30 seconds", "correct_choice": "b", "rationale": "A 5-minute no-touch observation period is the common U.S. standard to minimize the risk of autoresuscitation while preserving public trust and procedural consistency.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q11", "question_number": 11, "stem": "Which organ has the LONGEST typical out-of-body preservation window in DCD workflow? ]", "choice_a": "Heart", "choice_b": "Liver", "choice_c": "Kidneys", "choice_d": "Lungs", "correct_choice": "c", "rationale": "Kidneys tolerate the longest cold ischemia (~24–36 h), which is why they are usually recovered last in the multi-organ sequence.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q12", "question_number": 12, "stem": "During TA-NRP, which team member is most directly responsible for managing extracorporeal circuit flow, sweep, and hemofilter parameters? ]", "choice_a": "OPO coordinator", "choice_b": "Thoracic surgeon", "choice_c": "CRNA", "choice_d": "Perfusionist", "correct_choice": "d", "rationale": "The perfusionist manages the extracorporeal circuit; the CRNA supports metabolic, hemodynamic, and documentation goals in parallel and communicates with the perfusion team.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q13", "question_number": 13, "stem": "Excessive crystalloid administration should specifically be AVOIDED when which organ is being considered for procurement? ]", "choice_a": "Lungs", "choice_b": "Pancreas", "choice_c": "Liver", "choice_d": "Kidneys", "correct_choice": "a", "rationale": "Fluid overload worsens pulmonary edema and reduces lung suitability. Balanced resuscitation is preferred; excess crystalloid is avoided when lungs are planned for recovery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q14", "question_number": 14, "stem": "In the 2024 UNOS analysis of 918 DCD heart transplants by Madan and colleagues, 1-year survival with NRP versus direct procurement and perfusion (DPP) was approximately: ]", "choice_a": "NRP 85% vs DPP 85%", "choice_b": "NRP 95.2% vs DPP 90.1%", "choice_c": "NRP 100% vs DPP 100%", "choice_d": "NRP 78% vs DPP 85%", "correct_choice": "b", "rationale": "NRP 1-year survival was 95.2% (95% CI 92.3–98.2) vs DPP 90.1% (87.4–92.8), log-rank p=0.005; adjusted HR 0.39 (95% CI 0.22–0.70), p=0.002. Donor heart discard was 1.4% NRP vs 9.6% DPP.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q15", "question_number": 15, "stem": "A CRNA is asked to administer heparin for a TA-NRP case. The correct action is to: ]", "choice_a": "Administer heparin immediately at the start of the withdrawal phase", "choice_b": "Give heparin only after cross-clamp", "choice_c": "Administer heparin per program protocol — typically after death declaration and prior to cannulation", "choice_d": "Refuse to administer heparin because it violates the dead donor rule", "correct_choice": "c", "rationale": "Heparin timing in TA-NRP is program-specific but is typically given after death declaration and prior to cannulation. Giving heparin before death declaration for donation purposes may violate ethical safeguards; program protocol takes precedence.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q16", "question_number": 16, "stem": "Which finding most likely indicates diabetes insipidus in a brain-dead donor? ]", "choice_a": "Polyuria with severe hyponatremia and concentrated urine", "choice_b": "Anuria with rising serum sodium", "choice_c": "Bradycardia with hyperkalemia", "choice_d": "Abrupt polyuria (>4 mL/kg/h) with rising serum sodium and dilute urine", "correct_choice": "d", "rationale": "Central diabetes insipidus after brain death causes abrupt polyuria with hypernatremia and dilute urine due to loss of ADH secretion.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q17", "question_number": 17, "stem": "Which statement about MAP targets in donor management is most accurate based on current consensus statements? ]", "choice_a": "Consensus statements differ: SCCM/ACCP/AOPO 2015 and JHLT 2020 use >60 mmHg while the Canadian 2020 guideline uses >65 mmHg", "choice_b": "MAP >50 mmHg is universally accepted", "choice_c": "MAP targets are not recommended in any consensus statement", "choice_d": "All consensus statements agree on MAP >70 mmHg", "correct_choice": "a", "rationale": "No universally accepted donor management goal bundle exists; MAP targets vary by consensus statement (SCCM/ACCP/AOPO 2015 >60, JHLT 2020 >60, Canadian 2020 >65).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q18", "question_number": 18, "stem": "In the Brazilian cluster-randomized DONORS trial of 1,535 potential brain-dead donors, the subgroup with checklist adherence >79% had a cardiac-arrest rate of: ]", "choice_a": "20% versus 25%", "choice_b": "5.3% versus 14.8% in comparison groups (p=0.006)", "choice_c": "Not reported", "choice_d": "No difference between groups", "correct_choice": "b", "rationale": "High checklist adherence was associated with a cardiac-arrest rate of 5.3% vs 14.8% (p=0.006) and higher organ yield, even though the overall trial did not significantly reduce the primary endpoint.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q19", "question_number": 19, "stem": "Which DCD NRP subtype is used specifically to recover BOTH thoracic and abdominal organs including the heart? ]", "choice_a": "Extracorporeal support for cerebral protection", "choice_b": "Cerebral NRP", "choice_c": "Thoracoabdominal NRP (TA-NRP)", "choice_d": "Abdominal NRP (A-NRP)", "correct_choice": "c", "rationale": "TA-NRP restores circulation to thoracic and abdominal organs so the heart and lungs, in addition to abdominal organs, can be evaluated and recovered in situ. A-NRP excludes the thoracic circulation.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q20", "question_number": 20, "stem": "Which statement about the ethical framework for TA-NRP is TRUE? ]", "choice_a": "The clinician declaring death may also be part of the transplant team", "choice_b": "Consent is not required for NRP because the donor is already dead", "choice_c": "The dead donor rule does not apply to NRP", "choice_d": "The decision to withdraw life-sustaining treatment must be made independently of the decision to donate", "correct_choice": "d", "rationale": "Foundational ethical safeguards include (a) the decision to withdraw life-sustaining treatment must be made independently of the decision to donate, (b) the clinician declaring death must be separate from the transplant team, and (c) the dead donor rule remains absolute.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q21", "question_number": 21, "stem": "Which medication is commonly continued as scheduled dosing or infusion in donor-management protocols to reduce inflammatory activation, improve vascular responsiveness, and — in some programs — support lung recovery? ]", "choice_a": "Methylprednisolone", "choice_b": "Furosemide", "choice_c": "Fentanyl", "choice_d": "Rocuronium", "correct_choice": "a", "rationale": "Corticosteroids such as methylprednisolone are commonly used in donor-management protocols for their anti-inflammatory and vascular-responsiveness effects and, in some pathways, to support lung recovery.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q22", "question_number": 22, "stem": "Which term describes the period when organ perfusion becomes critically inadequate (severe hypotension, hypoxemia, or both) until cold flush or reperfusion begins in DCD? ]", "choice_a": "Agonal phase", "choice_b": "Functional warm ischemia", "choice_c": "Cold ischemia", "choice_d": "Asystolic time", "correct_choice": "b", "rationale": "Functional warm ischemia is defined by physiologic thresholds and is often more clinically relevant than the total agonal interval because organ injury depends on how long perfusion is insufficient.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q23", "question_number": 23, "stem": "Which of the following is NOT an appropriate CRNA action before cross-clamp in a DBD procurement case? ]", "choice_a": "Anticipating hypotension during positioning, incision, and sternotomy", "choice_b": "Confirming vasoactive infusions and backup medications are available", "choice_c": "Administering opioid boluses because the donor may ''feel pain'' from surgical stimulation", "choice_d": "Communicating with abdominal and thoracic teams before cannulation and cross-clamp", "correct_choice": "c", "rationale": "Opioid boluses are not required because the BD/DNC donor cannot experience pain or awareness. Spinal reflex movements may occur; neuromuscular blockade and vasoactive management are the appropriate responses.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q24", "question_number": 24, "stem": "Which statement about NRP versus normothermic machine perfusion (NMP) of DCD kidneys is supported by the 2025 Transplantation systematic review (Rijkse et al.)? ]", "choice_a": "Both had DGF rates >80%", "choice_b": "Neither modality improved on cold static storage", "choice_c": "NMP DGF was lower than NRP DGF", "choice_d": "NRP DGF (~24.6%) was lower than NMP DGF (~54.3%) with similar graft utilization", "correct_choice": "d", "rationale": "The systematic review reported NRP DGF ~24.6% vs NMP DGF ~54.3%, with similar primary nonfunction and graft utilization; both are characterized as feasible strategies likely improved compared with cold-stored DCD kidneys.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_1", "question_id": "course_2_module_1_q25", "question_number": 25, "stem": "Which action best exemplifies protocolized, evidence-informed CRNA practice during donor procurement based on contemporary (2023–2026) evidence? ]", "choice_a": "Following a program-specific donor-management checklist and documenting time-critical events in real time", "choice_b": "Deferring lung-protective ventilation once BD/DNC is declared", "choice_c": "Empirically starting IV levothyroxine on every unstable brain-dead heart donor", "choice_d": "Avoiding vasopressors to prevent ''over-treating'' the donor", "correct_choice": "a", "rationale": "Contemporary evidence (DONORS trial, Lele et al. 2025 multicenter analysis) supports protocolized, checklist-driven donor care with meticulous real-time documentation. Routine IV levothyroxine is no longer supported (Dhar et al. 2023).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module1_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
commit;